const isTimeoutError = e => e.name === 'TimeoutError'

/**
 * @param {Error} cause
 * @param {string} prefix
 * @param {number|string} timeout
 */
const getTimeoutError = (cause, prefix, timeout) =>
  Object.assign(new Error(`${prefix} exceeded timeout of ${typeof timeout === 'number' ? `${timeout}ms` : timeout}.`), {
    cause
  })

module.exports = { isTimeoutError, getTimeoutError }
